// Compares the files in your Drive folder with what is already indexed.
// New or edited files are (re)indexed, deleted files are removed from the knowledge base.
const SUPPORTED = [
  'application/vnd.google-apps.document',
  'application/vnd.google-apps.spreadsheet',
  'application/vnd.google-apps.presentation',
  'application/pdf', 'text/plain', 'text/markdown', 'text/csv',
];
const files = $('List Google Drive Files').all().map(i => i.json || {})
  .filter(f => f.id && SUPPORTED.includes(f.mimeType));
const indexed = {};
for (const item of $input.all()) {
  const c = item.json || {};
  if (c.file_id) indexed[c.file_id] = { modified: c.modified_time, name: c.file_name };
}
// Safety: an empty listing (wrong folder ID, missing access) never wipes the knowledge base.
if (!files.length) return [];

const out = [];
for (const f of files) {
  if (!indexed[f.id] || indexed[f.id].modified !== f.modifiedTime) {
    out.push({ json: { file_id: f.id, file_name: f.name, mime_type: f.mimeType, modified_time: f.modifiedTime, action: 'index' } });
  }
}
const live = new Set(files.map(f => f.id));
for (const id of Object.keys(indexed)) {
  if (!live.has(id)) out.push({ json: { file_id: id, file_name: indexed[id].name, action: 'remove' } });
}
return out;

// Splits each document into overlapping chunks of about chunkSize characters,
// cutting at paragraph or sentence ends where possible.
const cfg = $('Set Configuration Fields').first().json;
const size = Number(cfg.chunkSize || 1200);
const overlap = Number(cfg.chunkOverlap || 200);
const MAX_CHUNKS = 500;

function split(text) {
  const clean = String(text || '').replace(/\r/g, '').replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  const parts = [];
  let start = 0;
  while (start < clean.length && parts.length < MAX_CHUNKS) {
    let end = Math.min(start + size, clean.length);
    if (end < clean.length) {
      const para = clean.lastIndexOf('\n\n', end);
      const sentence = clean.lastIndexOf('. ', end);
      if (para > start + size / 2) end = para;
      else if (sentence > start + size / 2) end = sentence + 1;
    }
    const piece = clean.slice(start, end).trim();
    if (piece) parts.push(piece);
    if (end >= clean.length) break;
    start = Math.max(end - overlap, start + 1);
  }
  return parts;
}

const out = [];
$input.all().forEach((item, i) => {
  const file = $('Filter Files to Index').itemMatching(i).json;
  const text = typeof item.json.text === 'string' ? item.json.text : (typeof item.json.data === 'string' ? item.json.data : '');
  const chunks = split(text).map(c => 'Document: ' + file.file_name + '\n' + c);
  if (!chunks.length) return;
  out.push({ json: { file_id: file.file_id, file_name: file.file_name, modified_time: file.modified_time, chunks }, pairedItem: { item: i } });
});
return out;

// Pairs every chunk with its embedding and prepares rows for the knowledge base table.
const files = $('Split Document into Chunks').all();
const out = [];
$input.all().forEach((item, i) => {
  const file = files[i] && files[i].json;
  const data = (item.json.data || []).slice().sort((a, b) => a.index - b.index);
  if (!file || data.length !== file.chunks.length) return;
  data.forEach((d, n) => {
    out.push({
      json: {
        file_id: file.file_id,
        file_name: file.file_name,
        modified_time: file.modified_time,
        chunk_index: n,
        text: file.chunks[n],
        embedding: JSON.stringify(d.embedding.map(x => Math.round(x * 1e5) / 1e5)),
      },
    });
  });
});
return out;

// Turns the WhatsApp webhook into one clean item per customer message.
// Delivery and read receipts are already filtered out by the trigger settings.
const cfg = $('Set Configuration Fields').first().json;
const maxAgeSeconds = Number(cfg.ignoreMessagesOlderThanMinutes || 15) * 60;
const nowSeconds = Math.floor(Date.now() / 1000);
const out = [];

for (const item of $input.all()) {
  const event = item.json || {};
  const messages = Array.isArray(event.messages) ? event.messages : [];
  const contacts = Array.isArray(event.contacts) ? event.contacts : [];
  const phoneNumberId = (event.metadata && event.metadata.phone_number_id) || '';

  for (const m of messages) {
    if (!m || !m.id || !m.from) continue;
    if (['reaction', 'system', 'ephemeral', 'request_welcome'].includes(m.type)) continue;
    if (nowSeconds - Number(m.timestamp || nowSeconds) > maxAgeSeconds) continue;

    const contact = contacts.find(c => c.wa_id === m.from) || contacts[0] || {};
    let kind = 'text';
    let content = '';
    let mediaId = '';

    if (m.type === 'text') content = (m.text && m.text.body) || '';
    else if (m.type === 'button') content = (m.button && (m.button.text || m.button.payload)) || '';
    else if (m.type === 'interactive') {
      const i = m.interactive || {};
      content = (i.button_reply && i.button_reply.title) || (i.list_reply && i.list_reply.title) || '';
    } else if (m.type === 'audio') {
      kind = 'audio';
      mediaId = (m.audio && m.audio.id) || '';
      if (!mediaId) continue;
    } else {
      const caption = (m[m.type] && m[m.type].caption) || '';
      content = '[The customer sent a ' + m.type + ' that this assistant cannot open' + (caption ? '. Caption: "' + caption + '"' : '') + ']';
    }

    if (kind === 'text' && !String(content).trim()) continue;
    out.push({
      json: {
        message_id: m.id,
        phone: m.from,
        contact_name: (contact.profile && contact.profile.name) || '',
        phone_number_id: phoneNumberId,
        kind,
        content: String(content).slice(0, 4000),
        media_id: mediaId,
      },
    });
  }
}
return out;

// Decides who answers: the AI, or a team member who has taken over this chat.
// A chat stays with the team until humanTimeoutMinutes after their last reply, or until they send #bot on.
const now = Date.now();
const saved = $('Save to Customer Messages').all().map(i => i.json);
const incoming = $('Filter Seen Messages').all().map(i => i.json);
const chats = $input.all().map(i => i.json || {}).filter(c => c.phone);

return saved.map(m => {
  const src = incoming.find(x => x.message_id === m.message_id) || {};
  const chat = chats.find(c => c.phone === m.phone) || {};
  const humanActive = chat.mode === 'human' && Number(chat.human_until || 0) > now;
  return {
    json: {
      phone: m.phone,
      message_id: m.message_id,
      content: m.content,
      contact_name: src.contact_name || chat.contact_name || '',
      phone_number_id: src.phone_number_id || chat.phone_number_id || '',
      human_active: humanActive,
      mode: humanActive ? 'human' : 'bot',
      last_customer_at: now,
    },
  };
});

