// Retrieval: compares the question with every document chunk (cosine similarity)
// and keeps the best matches. Also prepares the recent conversation for context.
const cfg = $('Set Configuration Fields').first().json;
const questions = $('Check Human Handling Chat').all(1);
const embeddings = $input.all();
const topK = Number(cfg.topPassages || 5);
const minScore = Number(cfg.minRelevance || 0.3);
const maxHistory = Number(cfg.memoryMessages || 10);

const chunks = [];
const seen = new Set();
for (const item of $('Fetch Knowledge Base Data').all()) {
  const c = item.json || {};
  if (!c.text || !c.embedding || seen.has(c.id)) continue;
  seen.add(c.id);
  let vector;
  try { vector = JSON.parse(c.embedding); } catch (e) { continue; }
  if (Array.isArray(vector) && vector.length) chunks.push({ file_name: c.file_name, text: c.text, vector });
}

const history = $('Retrieve Recent Conversation').all().map(i => i.json || {}).filter(r => r.message_id);
const label = { customer: 'Customer', bot: 'You', staff: 'Team member' };

function cosine(a, b) {
  let dot = 0, na = 0, nb = 0;
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) { dot += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; }
  return na && nb ? dot / Math.sqrt(na * nb) : 0;
}

return questions.map((q, i) => {
  const ask = q.json;
  const e = embeddings[i] && embeddings[i].json;
  const qv = e && e.data && e.data[0] && e.data[0].embedding;
  const ranked = Array.isArray(qv)
    ? chunks.map(c => ({ file_name: c.file_name, text: c.text, score: cosine(qv, c.vector) }))
        .filter(c => c.score >= minScore)
        .sort((a, b) => b.score - a.score)
        .slice(0, topK)
    : [];
  const past = history
    .filter(r => r.phone === ask.phone && r.message_id !== ask.message_id)
    .sort((a, b) => Number(a.id) - Number(b.id))
    .slice(-maxHistory);
  return {
    json: {
      ...ask,
      documents: ranked.length
        ? ranked.map((c, n) => '[' + (n + 1) + '] From "' + c.file_name + '":\n' + c.text).join('\n\n')
        : 'No matching passages were found in the knowledge base.',
      conversation: past.length
        ? past.map(r => (label[r.role] || r.role) + ': ' + String(r.content).slice(0, 800)).join('\n')
        : 'No earlier messages.',
      best_score: ranked.length ? Number(ranked[0].score.toFixed(3)) : 0,
      sources: [...new Set(ranked.map(c => c.file_name))].join(', '),
    },
  };
});

