// Reads the AI decision and prepares the reply. Anything that is not a clear answer goes to the team.
const cfg = $('Set Configuration Fields').first().json;
const allowed = ['answered', 'not_in_docs', 'wants_human'];

return $input.all().map((item, i) => {
  const q = $('Locate Relevant Answers').itemMatching(i).json;
  const o = item.json.output || {};
  let status = allowed.includes(o.status) ? o.status : 'not_in_docs';
  let reply = String(o.reply || '').trim()
    .replace(/\*\*(.+?)\*\*/g, '*$1*')
    .replace(/^#{1,6}\s*(.+)$/gm, '*$1*')
    .slice(0, 3900);
  if (!reply) { status = status === 'answered' ? 'not_in_docs' : status; reply = cfg.handoffReply; }
  return {
    json: {
      ...q,
      reply,
      status,
      answered: status === 'answered',
      question_summary: String(o.question_summary || q.content || '').slice(0, 300),
    },
    pairedItem: { item: i },
  };
});

