// Reads replies from your team in the Telegram group. A reply must answer one of the
// bot's handoff messages, because those contain the #wa tag with the customer's number.
const cfg = $('Set Configuration Fields').first().json;
const out = [];
for (const item of $input.all()) {
  const msg = item.json.message || {};
  if (String(msg.chat && msg.chat.id) !== String(cfg.telegramChatId)) continue;
  const text = String(msg.text || msg.caption || '').trim();
  const original = msg.reply_to_message || {};
  const tag = String(original.text || original.caption || '').match(/#wa(\d{6,15})/);
  if (!tag || !text) continue;
  out.push({
    json: {
      phone: tag[1],
      text,
      command: /^#bot\s*on\b/i.test(text) ? 'bot_on' : 'send',
      staff_name: [msg.from && msg.from.first_name, msg.from && msg.from.last_name].filter(Boolean).join(' '),
      telegram_message_id: msg.message_id,
    },
  });
}
return out;

// WhatsApp only allows free-form messages within 24 hours of the customer's last message.
// Outside that window the reply is not sent and the team is told why.
const now = Date.now();
const DAY = 24 * 60 * 60 * 1000;
const chats = $input.all().map(i => i.json || {}).filter(c => c.phone);

return $('Parse Team Telegram Reply').all().map(r => {
  const s = r.json;
  const chat = chats.find(c => c.phone === s.phone);
  let action = 'send';
  let notice = '';
  if (!chat) {
    action = 'notify';
    notice = 'No WhatsApp chat found for +' + s.phone + '. Nothing was sent.';
  } else if (s.command === 'bot_on') {
    action = 'bot_on';
    notice = 'The AI assistant is answering +' + s.phone + ' again.';
  } else if (now - Number(chat.last_customer_at || 0) > DAY) {
    action = 'notify';
    notice = 'Not sent: +' + s.phone + ' last wrote more than 24 hours ago, so WhatsApp only allows approved template messages now.';
  }
  return {
    json: {
      ...s,
      action,
      notice,
      phone_number_id: chat ? chat.phone_number_id : '',
      contact_name: chat ? chat.contact_name : '',
    },
  };
});
